package numeric

import (
	"context"
	"encoding/json"
	"math"
	"os"
	"testing"
)

// Reference values come from testdata/scipy_refs.json, generated by
// testdata/refs.py with scipy 1.18.1, numpy 2.5.4 and statsmodels 0.15.0
// (python3 -I testdata/refs.py > testdata/scipy_refs.json).

type refs struct {
	Dist []struct {
		Dist   string             `json:"dist"`
		Params map[string]float64 `json:"params"`
		Fn     string             `json:"fn"`
		At     float64            `json:"at"`
		Want   any                `json:"want"`
	} `json:"dist"`
	Solve struct {
		A [][]float64
		B []float64
		X []float64
	} `json:"solve"`
	Inv struct {
		A   [][]float64
		Inv [][]float64
		Det float64
	} `json:"inv"`
	Eigh struct {
		A       [][]float64
		Values  []float64
		Vectors [][]float64
	} `json:"eigh"`
	Lstsq struct {
		A   [][]float64
		B   []float64
		X   []float64
		SSR float64
	} `json:"lstsq"`
	OLS struct {
		Rows                   []map[string]float64
		Coef, SE, T, P, Lo, Hi []float64
		R2, AdjR2, F, FP       float64
		Sigma                  float64
		DF                     int
	} `json:"ols"`
	OLSNoInt struct {
		Coef, SE         []float64
		R2, AdjR2, F, FP float64
	} `json:"ols_noint"`
	ExpFit struct {
		X, Y, P, SE []float64
		SSR         float64
	} `json:"expfit"`
	Raman struct {
		X, Y, P0, P, SE []float64
		SSR             float64
	} `json:"raman"`
	Brentq float64            `json:"brentq"`
	Quad   map[string]float64 `json:"quad"`
	Spline struct {
		Xs, Ys, At, Want, Lin []float64
	} `json:"spline"`
	Trapz float64 `json:"trapz"`
	TTest struct {
		A, B, C                                             []float64
		One, OneGreater, Welch, Student, Paired, PairedLess tref
	} `json:"ttest"`
	Wilson struct{ K, N, Lo, Hi float64 } `json:"wilson"`
}

type tref struct {
	T, P, DF float64
	Lo, Hi   any
}

func loadRefs(t *testing.T) *refs {
	t.Helper()
	b, err := os.ReadFile("testdata/scipy_refs.json")
	if err != nil {
		t.Fatal(err)
	}
	var r refs
	if err := json.Unmarshal(b, &r); err != nil {
		t.Fatal(err)
	}
	return &r
}

func refNum(v any) float64 {
	switch x := v.(type) {
	case float64:
		return x
	case string:
		if x == "inf" {
			return math.Inf(1)
		}
		return math.Inf(-1)
	}
	return math.NaN()
}

// close reports |got - want| <= rel*|want| + abs.
func near(got, want, rel, abs float64) bool {
	if math.IsInf(want, 0) || math.IsNaN(want) {
		return got == want || (math.IsNaN(got) && math.IsNaN(want))
	}
	return math.Abs(got-want) <= rel*math.Abs(want)+abs
}

func TestDistributionsMatchScipy(t *testing.T) {
	r := loadRefs(t)
	for _, c := range r.Dist {
		spec, ok := FindDist(c.Dist)
		if !ok {
			t.Fatalf("no dist %s", c.Dist)
		}
		ps := make([]float64, len(spec.Params))
		for i, p := range spec.Params {
			v, ok := c.Params[p.Name]
			if !ok {
				v = p.Default
			}
			ps[i] = v
		}
		d, err := spec.Make(ps)
		if err != nil {
			t.Fatal(err)
		}
		var got float64
		switch c.Fn {
		case "pdf":
			got = d.PDF(c.At)
		case "cdf":
			got = d.CDF(c.At)
		case "sf":
			got = d.SF(c.At)
		case "ppf":
			got = d.PPF(c.At)
		}
		want := refNum(c.Want)
		rel := 1e-10
		if c.Fn == "ppf" {
			rel = 1e-9
		}
		if !near(got, want, rel, 1e-300) {
			t.Errorf("%s%v.%s(%v) = %.17g, scipy %.17g (rel err %.2g)", c.Dist, c.Params, c.Fn, c.At, got, want, math.Abs(got-want)/math.Abs(want))
		}
	}
}

func TestLinalgMatchesNumpy(t *testing.T) {
	r := loadRefs(t)
	b := make([][]float64, len(r.Solve.B))
	for i, v := range r.Solve.B {
		b[i] = []float64{v}
	}
	x, err := FactorLU(r.Solve.A).Solve(b)
	if err != nil {
		t.Fatal(err)
	}
	for i := range x {
		if !near(x[i][0], r.Solve.X[i], 1e-13, 1e-14) {
			t.Errorf("solve x[%d] = %v, numpy %v", i, x[i][0], r.Solve.X[i])
		}
	}
	lu := FactorLU(r.Inv.A)
	inv, _ := lu.Inverse()
	for i := range inv {
		for j := range inv[i] {
			if !near(inv[i][j], r.Inv.Inv[i][j], 1e-13, 1e-15) {
				t.Errorf("inv[%d][%d] = %v, numpy %v", i, j, inv[i][j], r.Inv.Inv[i][j])
			}
		}
	}
	if !near(lu.Det(), r.Inv.Det, 1e-13, 0) {
		t.Errorf("det = %v, numpy %v", lu.Det(), r.Inv.Det)
	}
	vals, vecs, err := SymEig(r.Eigh.A)
	if err != nil {
		t.Fatal(err)
	}
	for i := range vals {
		if !near(vals[i], r.Eigh.Values[i], 1e-13, 1e-14) {
			t.Errorf("eig value %d = %v, numpy %v", i, vals[i], r.Eigh.Values[i])
		}
		// numpy's sign is arbitrary: compare up to sign.
		s := 0.0
		for k := range vecs[i] {
			s += vecs[i][k] * r.Eigh.Vectors[i][k]
		}
		if !near(math.Abs(s), 1, 1e-12, 0) {
			t.Errorf("eig vector %d = %v, numpy %v", i, vecs[i], r.Eigh.Vectors[i])
		}
	}
	if _, _, err := SymEig([][]float64{{1, 2}, {3, 4}}); err != ErrNotSymmetric {
		t.Errorf("non-symmetric: %v", err)
	}
	ls, _, err := Lstsq(r.Lstsq.A, r.Lstsq.B)
	if err != nil {
		t.Fatal(err)
	}
	for i := range ls {
		if !near(ls[i], r.Lstsq.X[i], 1e-13, 1e-14) {
			t.Errorf("lstsq x[%d] = %v, numpy %v", i, ls[i], r.Lstsq.X[i])
		}
	}
	if _, dep, err := Lstsq([][]float64{{1, 2}, {2, 4}, {3, 6}}, []float64{1, 2, 3}); err != ErrSingular || dep != 1 {
		t.Errorf("dependent columns: dep %d err %v", dep, err)
	}
	if !FactorLU([][]float64{{1, 2}, {2, 4}}).Singular {
		t.Error("singular not detected")
	}
}

func TestOLSMatchesStatsmodels(t *testing.T) {
	r := loadRefs(t)
	o := r.OLS
	var x, x0 [][]float64
	var y []float64
	for _, row := range o.Rows {
		x = append(x, []float64{1, row["price"], row["ads"]})
		x0 = append(x0, []float64{row["price"], row["ads"]})
		y = append(y, row["sales"])
	}
	g, _, err := OLS(x, y, true, 0.95)
	if err != nil {
		t.Fatal(err)
	}
	for j := range g.Coef {
		for _, c := range []struct {
			name      string
			got, want float64
		}{{"coef", g.Coef[j], o.Coef[j]}, {"se", g.StdErr[j], o.SE[j]}, {"t", g.T[j], o.T[j]},
			{"p", g.P[j], o.P[j]}, {"lo", g.CI[j][0], o.Lo[j]}, {"hi", g.CI[j][1], o.Hi[j]}} {
			if !near(c.got, c.want, 1e-9, 1e-300) {
				t.Errorf("%s[%d] = %.17g, statsmodels %.17g", c.name, j, c.got, c.want)
			}
		}
	}
	for _, c := range []struct {
		name      string
		got, want float64
	}{{"r2", g.R2, o.R2}, {"adjR2", g.AdjR2, o.AdjR2}, {"F", g.F, o.F}, {"Fp", g.FP, o.FP}, {"sigma", g.Sigma, o.Sigma}} {
		if !near(c.got, c.want, 1e-9, 1e-300) {
			t.Errorf("%s = %.17g, statsmodels %.17g", c.name, c.got, c.want)
		}
	}
	if g.DF != o.DF {
		t.Errorf("df %d, statsmodels %d", g.DF, o.DF)
	}
	g0, _, err := OLS(x0, y, false, 0.95)
	if err != nil {
		t.Fatal(err)
	}
	n0 := r.OLSNoInt
	for j := range g0.Coef {
		if !near(g0.Coef[j], n0.Coef[j], 1e-9, 0) || !near(g0.StdErr[j], n0.SE[j], 1e-9, 0) {
			t.Errorf("no intercept coef %d: %v ± %v, statsmodels %v ± %v", j, g0.Coef[j], g0.StdErr[j], n0.Coef[j], n0.SE[j])
		}
	}
	for _, c := range [][2]float64{{g0.R2, n0.R2}, {g0.AdjR2, n0.AdjR2}, {g0.F, n0.F}, {g0.FP, n0.FP}} {
		if !near(c[0], c[1], 1e-9, 1e-300) {
			t.Errorf("no intercept stat %v, statsmodels %v", c[0], c[1])
		}
	}
}

func fitModel(x []float64, f func(x float64, p []float64) float64) func(p, out []float64) {
	return func(p, out []float64) {
		for i, xi := range x {
			out[i] = f(xi, p)
		}
	}
}

func checkFit(t *testing.T, what string, res *FitResult, p, se []float64, ssr float64) {
	t.Helper()
	if res.Status != Converged {
		t.Errorf("%s: status %v", what, res.Status)
	}
	for j := range p {
		if !near(res.P[j], p[j], 1e-6, 1e-9) {
			t.Errorf("%s p[%d] = %.10g, scipy %.10g", what, j, res.P[j], p[j])
		}
		got := math.Sqrt(res.Cov[j*len(p)+j])
		if !near(got, se[j], 1e-3, 0) {
			t.Errorf("%s se[%d] = %.6g, scipy %.6g", what, j, got, se[j])
		}
	}
	if !near(res.SSR, ssr, 1e-8, 0) {
		t.Errorf("%s ssr = %.12g, scipy %.12g", what, res.SSR, ssr)
	}
}

func TestFitMatchesCurveFit(t *testing.T) {
	r := loadRefs(t)
	e := r.ExpFit
	res, err := Fit(context.Background(), FitProblem{
		Model: fitModel(e.X, func(x float64, p []float64) float64 { return p[0]*math.Exp(-p[1]*x) + p[2] }),
		Y:     e.Y, P0: []float64{1, 1, 0},
	})
	if err != nil {
		t.Fatal(err)
	}
	checkFit(t, "exp decay", res, e.P, e.SE, e.SSR)
}

// TestFitRamanPeaks fits two Lorentzians and a Gaussian on a linear
// baseline (601 points, noise sigma 2) and compares with scipy curve_fit.
func TestFitRamanPeaks(t *testing.T) {
	r := loadRefs(t)
	ra := r.Raman
	lor, _ := FindPeakShape("lorentzian")
	gau, _ := FindPeakShape("gaussian")
	model := func(x float64, p []float64) float64 {
		return lor.At(x, p[0:3]) + lor.At(x, p[3:6]) + gau.At(x, p[6:9]) + p[9] + p[10]*x
	}
	res, err := Fit(context.Background(), FitProblem{Model: fitModel(ra.X, model), Y: ra.Y, P0: ra.P0})
	if err != nil {
		t.Fatal(err)
	}
	checkFit(t, "raman", res, ra.P, ra.SE, ra.SSR)
	t.Logf("raman: %d iterations, %d evaluations, reason %s", res.Iterations, res.Evals, res.Reason)
}

// TestFitBoundedMatchesLeastSquares: the center bound keeps a pseudo-Voigt
// off the true peak; compare with scipy least_squares (trf, bounds).
func TestFitBoundedMatchesLeastSquares(t *testing.T) {
	b, err := os.ReadFile("testdata/scipy_refs.json")
	if err != nil {
		t.Fatal(err)
	}
	var all struct {
		Bounded struct {
			P0, P []float64
			SSR   float64
		} `json:"bounded"`
	}
	if err := json.Unmarshal(b, &all); err != nil {
		t.Fatal(err)
	}
	ref := all.Bounded
	var x, y []float64
	for i := 0; i <= 200; i++ {
		xi := 400 + float64(i)
		x = append(x, xi)
		y = append(y, 100/(1+4*math.Pow((xi-520)/8, 2))+5)
	}
	pv, _ := FindPeakShape("pseudovoigt")
	res, err := Fit(context.Background(), FitProblem{
		Model: fitModel(x, func(xi float64, p []float64) float64 { return pv.At(xi, p[:4]) + p[4] }),
		Y:     y, P0: ref.P0,
		Lo: []float64{500, math.Inf(-1), 1e-10, 0, math.Inf(-1)}, Hi: []float64{505, math.Inf(1), math.Inf(1), 1, math.Inf(1)},
	})
	if err != nil {
		t.Fatal(err)
	}
	if res.Status != Converged || !near(res.SSR, ref.SSR, 1e-8, 0) {
		t.Errorf("status %v ssr %.12g, scipy %.12g", res.Status, res.SSR, ref.SSR)
	}
	for j := range ref.P {
		if !near(res.P[j], ref.P[j], 1e-4, 1e-9) {
			t.Errorf("p[%d] = %.10g, scipy %.10g", j, res.P[j], ref.P[j])
		}
	}
	if res.P[0] != 505 || !res.AtBound[0] || !res.AtBound[3] {
		t.Errorf("bounds: p %v atBound %v", res.P, res.AtBound)
	}
}

func TestFitStatuses(t *testing.T) {
	x := []float64{0, 1, 2, 3, 4}
	y := []float64{1, 3, 5, 7, 9}
	line := fitModel(x, func(x float64, p []float64) float64 { return p[0] + p[1]*x })
	res, _ := Fit(context.Background(), FitProblem{Model: line, Y: y, P0: []float64{0, 0}})
	if res.Status != Converged || math.Abs(res.P[1]-2) > 1e-9 {
		t.Errorf("exact line: %v %v %s", res.Status, res.P, res.Reason)
	}
	// Iteration limit: honest status.
	r := loadRefs(t)
	e := r.ExpFit
	res, _ = Fit(context.Background(), FitProblem{
		Model: fitModel(e.X, func(x float64, p []float64) float64 { return p[0]*math.Exp(-p[1]*x) + p[2] }),
		Y:     e.Y, P0: []float64{1, 1, 0}, MaxIter: 2,
	})
	if res.Status != MaxIterations {
		t.Errorf("maxIter 2: %v", res.Status)
	}
	// Not identifiable: p0*p1 only.
	res, _ = Fit(context.Background(), FitProblem{
		Model: fitModel(x, func(x float64, p []float64) float64 { return p[0] * p[1] * x }),
		Y:     y, P0: []float64{1, 1},
	})
	if res.Cov != nil || res.Dependent < 0 {
		t.Errorf("unidentifiable: cov %v dep %d", res.Cov, res.Dependent)
	}
	// Bounds hold.
	res, _ = Fit(context.Background(), FitProblem{Model: line, Y: y, P0: []float64{0, 0}, Hi: []float64{math.Inf(1), 1.5}})
	if res.P[1] != 1.5 || !res.AtBound[1] {
		t.Errorf("bound: %v %v", res.P, res.AtBound)
	}
	if _, err := Fit(context.Background(), FitProblem{Model: fitModel(x, func(x float64, p []float64) float64 { return math.Log(p[0]) }), Y: y, P0: []float64{-1}}); err != ErrBadStart {
		t.Errorf("bad start: %v", err)
	}
}

func TestRootMinimizeIntegrate(t *testing.T) {
	r := loadRefs(t)
	f := func(x float64) float64 { return x*x*x - 2*x - 5 }
	rr := Brent(f, 2, 3, f(2), f(3), 1e-15, 4*eps, 100)
	if rr.Status != Converged || !near(rr.X, r.Brentq, 1e-15, 0) {
		t.Errorf("brent: %+v, scipy %v", rr, r.Brentq)
	}
	rosen := func(p []float64) float64 {
		return 100*(p[1]-p[0]*p[0])*(p[1]-p[0]*p[0]) + (1-p[0])*(1-p[0])
	}
	m := NelderMead(context.Background(), rosen, []float64{-1.2, 1}, MinimizeOptions{})
	if m.Status != Converged || math.Abs(m.X[0]-1) > 1e-6 || math.Abs(m.X[1]-1) > 1e-6 {
		t.Errorf("rosenbrock: %+v", m)
	}
	m = NelderMead(context.Background(), rosen, []float64{-1.2, 1}, MinimizeOptions{MaxIter: 10})
	if m.Status != MaxIterations {
		t.Errorf("maxIter: %v", m.Status)
	}
	// Bounded: minimum of (x-3)^2 on [0, 2] is at 2.
	m = NelderMead(context.Background(), func(p []float64) float64 { return (p[0] - 3) * (p[0] - 3) }, []float64{1}, MinimizeOptions{Lo: []float64{0}, Hi: []float64{2}})
	if math.Abs(m.X[0]-2) > 1e-8 {
		t.Errorf("bounded: %+v", m)
	}
	ctx := context.Background()
	for name, c := range map[string]struct {
		f    func(float64) float64
		a, b float64
	}{
		"exp_sq_0_1":    {func(x float64) float64 { return math.Exp(-x * x) }, 0, 1},
		"exp_sq_inf":    {func(x float64) float64 { return math.Exp(-x * x) }, math.Inf(-1), math.Inf(1)},
		"lorentz_0_inf": {func(x float64) float64 { return 1 / (1 + x*x) }, 0, math.Inf(1)},
		"sin_0_pi":      {math.Sin, 0, math.Pi},
	} {
		res := Integrate(ctx, c.f, c.a, c.b, 1e-13, 1e-13, 200)
		if res.Status != Converged || !near(res.Value, r.Quad[name], 1e-12, 0) {
			t.Errorf("%s: %+v, scipy %v", name, res, r.Quad[name])
		}
	}
	res := Integrate(ctx, func(x float64) float64 { return 1 / math.Sqrt(x) }, 0, 1, 1e-10, 1e-10, 200)
	if math.Abs(res.Value-2) > 1e-6 {
		t.Errorf("1/sqrt(x): %+v", res)
	}
	if Integrate(ctx, math.Sin, 0, 100, 1e-14, 1e-14, 2).Status != MaxIterations {
		t.Error("segment limit not reported")
	}
}

func TestInterpMatchesScipy(t *testing.T) {
	r := loadRefs(t)
	s := r.Spline
	sp := NewSpline(s.Xs, s.Ys)
	for i, x := range s.At {
		if got := sp.At(x); !near(got, s.Want[i], 1e-12, 1e-14) {
			t.Errorf("spline(%v) = %.17g, scipy %.17g", x, got, s.Want[i])
		}
	}
	lin := NewLinear(s.Xs, s.Ys)
	for i, want := range s.Lin {
		if got := lin.At(s.At[i]); !near(got, want, 1e-14, 1e-15) {
			t.Errorf("linear(%v) = %v, numpy %v", s.At[i], got, want)
		}
	}
	if got := Trapezoid(s.Xs, s.Ys); !near(got, r.Trapz, 1e-14, 0) {
		t.Errorf("trapezoid %v, numpy %v", got, r.Trapz)
	}
}

func TestTTestsMatchScipy(t *testing.T) {
	r := loadRefs(t)
	tt := r.TTest
	diff := make([]float64, len(tt.A))
	for i := range diff {
		diff[i] = tt.A[i] - tt.C[i]
	}
	for name, c := range map[string]struct {
		got TTestResult
		ref tref
	}{
		"one":        {TTest1(tt.A, 5, TwoSided, 0.95), tt.One},
		"oneGreater": {TTest1(tt.A, 5, Greater, 0.95), tt.OneGreater},
		"welch":      {TTest2(tt.A, tt.B, 0, false, TwoSided, 0.95), tt.Welch},
		"student90":  {TTest2(tt.A, tt.B, 0, true, TwoSided, 0.90), tt.Student},
		"paired":     {TTest1(diff, 0, TwoSided, 0.95), tt.Paired},
		"pairedLess": {TTest1(diff, 0, Less, 0.95), tt.PairedLess},
	} {
		g, w := c.got, c.ref
		for _, v := range [][2]float64{{g.T, w.T}, {g.P, w.P}, {g.DF, w.DF}, {g.CI[0], refNum(w.Lo)}, {g.CI[1], refNum(w.Hi)}} {
			if !near(v[0], v[1], 1e-10, 1e-300) {
				t.Errorf("%s: got %+v, scipy %+v", name, g, w)
				break
			}
		}
	}
	lo, hi := WilsonCI(r.Wilson.K, r.Wilson.N, 0.95)
	if !near(lo, r.Wilson.Lo, 1e-12, 0) || !near(hi, r.Wilson.Hi, 1e-12, 0) {
		t.Errorf("wilson [%v, %v], statsmodels [%v, %v]", lo, hi, r.Wilson.Lo, r.Wilson.Hi)
	}
}

func TestRNGRepeatable(t *testing.T) {
	a, b := NewRNG(42), NewRNG(42)
	for range 100 {
		if a.Float64() != b.Float64() || a.Normal() != b.Normal() || a.Below(7) != b.Below(7) {
			t.Fatal("same seed, different stream")
		}
	}
	// Golden values pin the stream: a change here breaks users' seeds.
	g := NewRNG(1)
	if got := []float64{g.Float64(), g.Normal(), float64(g.Below(100))}; got[0] != 0.5274601051088775 || got[1] != -1.0389180271685035 || got[2] != 65 {
		t.Errorf("seed 1 stream changed: %v", got)
	}
	// Moments of 200k normals.
	r := NewRNG(7)
	xs := make([]float64, 200000)
	for i := range xs {
		xs[i] = r.Normal()
	}
	m, v := MeanVar(xs)
	if math.Abs(m) > 0.01 || math.Abs(v-1) > 0.01 {
		t.Errorf("normal moments %v %v", m, v)
	}
	// Inversion draws from a Poisson(3) have mean 3.
	s := 0.0
	for range 50000 {
		s += r.Draw(Poisson{3})
	}
	if math.Abs(s/50000-3) > 0.03 {
		t.Errorf("poisson mean %v", s/50000)
	}
	p := r.Sample(10, 10)
	seen := map[int]bool{}
	for _, i := range p {
		seen[i] = true
	}
	if len(seen) != 10 {
		t.Errorf("sample not distinct: %v", p)
	}
}
